#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

const int64 MOD = 998244353LL;

int64 pw(int64 a, int64 b) {
    int64 res = 1;
    while (b > 0) {
        if (b & 1LL) {
            res = res * a % MOD;
        }
        a = a * a % MOD;
        b /= 2;
    }
    return res;
}

int64 inv(int64 a) {
    return pw(a, MOD - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tt = 1;
    vector<int64> f(500010, 1);
    for (int i = 2; i <= 500000; ++i) {
        f[i] = f[i - 1] * i % MOD;
    }

    while (tt-- > 0) {
        int n, k;
        cin >> n >> k;

        int64 ans = 0;
        for (int i = 1; i <= n - k + 1; ++i) {
            int cnt = n / i;
            if (cnt < k) {
                continue;
            }

            int64 sum = f[cnt - 1] * inv(f[k - 1]) % MOD;
            sum = inv(f[cnt - k]) * sum % MOD;
            ans = (ans + sum) % MOD;
        }

        cout << ans << '\n';
    }

    return 0;
}

